mapper.select:
select tab.* from ( select cprh.payment_req_number, cprl.payment_req_ln_id, cprl.source_doc_category, cprh.payment_req_id, (select su.description from sys_user su where su.user_id = cprl.created_by ) user_name, (select hci.description from con_contract_cashflow ccc,hls_cashflow_item hci,con_contract cc where ccc.cashflow_id = cprl.source_doc_line_id and hci.cf_item = ccc.cf_item and hci.cf_type = ccc.cf_type and cc.contract_id = ccc.contract_id and ccc.cf_direction='OUTFLOW' and cc.contract_status in ('SIGN','INCEPT')) description, cc.contract_id, cc.contract_name contract_name, cc.contract_number contract_number, cprl.amount, nvl(cprl.amount_paid,0) amount_paid, cprl.bp_bank_account_name, cprl.bp_bank_name, cprl.bp_bank_account_num, cprl.self_bank_account_id, cprl.self_bank_name, cprl.self_bank_branch_name, cprl.self_bank_account_num, cprl.self_bank_account_name, cprl.payment_method, cprl.bp_id, cprh.payment_req_date, hbm.bp_name from csh_payment_req_ln cprl, csh_payment_req_hd cprh, con_contract cc, hls_bp_master hbm WHERE cprl.payment_flag in ('NOT','PARTIAL') AND cc.contract_status IN ('SIGN','LOAN','INCEPT') and hbm.bp_id = cprl.bp_id and cprl.source_doc_category='CON_CONTRACT' and cprh.payment_req_id = cprl.payment_req_id and cprh.source_doc_id = cc.contract_id AND cprh.payment_req_status='APPROVED' and cc.company_id=#{request.companyId}
and cprh.payment_req_date >= #{queryDateFrom}
and cprh.payment_req_date <= #{queryDateTo}
AND cprh.currency in
#{item}
and (cc.contract_name like concat(concat('%',#{contractInfo}),'%') or cc.contract_number like concat(concat('%',#{contractInfo}),'%'))
and (cprl.bp_bank_account_name like concat(concat('%',#{bankInfo}),'%') or cprl.bp_bank_account_num like concat(concat('%',#{bankInfo}),'%'))
and (hbm.bp_name like concat(concat('%',#{payInfo}),'%') or hbm.bp_code like concat(concat('%',#{payInfo}),'%'))
UNION SELECT temp.* FROM (SELECT cprh.payment_req_number, cprl.payment_req_ln_id payment_req_ln_id, cprl.source_doc_category, cprh.payment_req_id, ( SELECT su.description FROM sys_user su WHERE su.user_id = cprl.created_by ) user_name, (select hci.DESCRIPTION from fct_quotation_cashflow fqc,hls_cashflow_item hci where cprl.source_doc_line_id = fqc.quotation_cashflow_id and HCI.CF_ITEM=FQC.CF_ITEM ) description, lc.contract_id, lc.contract_name, lc.contract_number, cprl.amount, nvl(cprl.amount_paid,0) amount_paid, cprl.bp_bank_account_name, cprl.bp_bank_name, cprl.bp_bank_account_num, cprl.self_bank_account_id, cprl.self_bank_name, cprl.self_bank_branch_name, cprl.self_bank_account_num, cprl.self_bank_account_name, cprl.payment_method, cprl.bp_id, cprh.payment_req_date, hbm.bp_name FROM csh_payment_req_ln cprl, csh_payment_req_hd cprh, fct_contract lc, hls_bp_master hbm
lc.contract_status IN ('SIGN','LOAN') AND cprh.document_type = 'PAYMENT_REQ' AND hbm.bp_id = cprl.bp_id and cprl.source_doc_category='FCT_CONTRACT' AND cprh.payment_req_id = cprl.payment_req_id AND cprh.source_doc_id = lc.contract_id AND cprl.payment_flag in ('NOT','PARTIAL') AND cprh.payment_req_status='APPROVED' and lc.company_id=#{request.companyId}
and cprh.payment_req_date >= #{queryDateFrom}
and cprh.payment_req_date <= #{queryDateTo}
AND cprh.currency in
#{item}
and (lc.contract_name like concat(concat('%',#{contractInfo}),'%') or lc.contract_number like concat(concat('%',#{contractInfo}),'%'))
and (cprl.bp_bank_name like concat(concat('%',#{bankInfo}),'%') or cprl.bp_bank_account_num like concat(concat('%',#{bankInfo}),'%'))
and (hbm.bp_name like concat(concat('%',#{payInfo}),'%') or hbm.bp_code like concat(concat('%',#{payInfo}),'%'))
) temp
)tab ORDER BY tab.payment_req_date DESC

select v.* from (SELECT (SELECT pq.currency FROM prj_quotation pq WHERE pq.QUOTATION_ID = cc.QUOTATION_ID ) AS currency, (SELECT pq.price_list FROM prj_quotation pq WHERE pq.QUOTATION_ID = cc.QUOTATION_ID ) price_list, cc.QUOTATION_ID, cc.contract_id, cc.contract_id AS funding_plan_id, cprh.payment_req_id, cprh.LOAN_TYPE, cprh.PAYMENT_TYPE, cprh.Payment_Req_Status, cprh.PAYMENT_APPROVED_STATUS, (SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'PAYMENT_APPROVED_STATUS' AND code_value = cprh.PAYMENT_APPROVED_STATUS) AS PAYMENT_APPROVED_STATUS_N, (SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'CSH.LOAN_TYPE' AND code_value = cprh.LOAN_TYPE) AS LOAN_TYPE_N, (SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'CSH701_TRANSACTION_TYPE' AND code_value = cprh.payment_type) AS PAYMENT_TYPE_N, (SELECT distinct e.NAME FROM sys_user s, sys_user_allocation a, fnd_employee e, fnd_employee_assigns fa WHERE s.user_id = a.user_id AND a.EMPLOYEE_ASSIGN_ID = fa.EMPLOYEE_ASSIGN_ID AND fa.EMPLOYEE_ID = e.EMPLOYEE_ID
and a.USER_ID=cprh.EMPLOYEE_ID and fa.PRIMARY_POSITION_FLAG = 'Y') AS project_manager_id_n, cprh.loan_total_amount, cprh.payment_req_number, (SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'HLS_WFL_STATUS' AND code_value = cprh.transfer_status) AS status_n, (select p.CONTRACT_NAME from prj_project p where p.project_id=cc.PROJECT_ID) contract_name, (select p.CONTRACT_NUMBER from prj_project p where p.project_id=cc.PROJECT_ID)contract_number, (select p.tenant_id from prj_project p where p.project_id=cc.PROJECT_ID) tenant_id, (SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = (select p.tenant_id from prj_project p where p.project_id=cc.PROJECT_ID)) AS bp_name, cc.contract_number AS defray_number, cc.legal_contract_number, cprh.proposed_launch_date, cprh.created_by, cprh.creation_date, (SELECT su.description FROM sys_user su WHERE su.user_id = cprh.created_by) AS application_name, cprh.creation_date AS application_date, cprh.process_instance_id, cc.CONTRACT_NUMBER AS FUNDING_PLAN_NUMBER, (SELECT pp.COMPANY_SPV FROM prj_project pp WHERE pp.PROJECT_ID = cc.PROJECT_ID) AS COMPANY_SPV, (SELECT t.company_full_name FROM fnd_company t WHERE t.company_id = (SELECT pp.COMPANY_SPV FROM prj_project pp WHERE pp.PROJECT_ID = cc.PROJECT_ID)) AS company_spv_n, ( SELECT tc.PROJECT_ID FROM con_contract tc WHERE tc.CONTRACT_ID = cprh.SOURCE_CONTRACT_ID ) PROJECT_ID, ( SELECT nvl( cprh.LOAN_TOTAL_AMOUNT, 0 ) - nvl( sum( lnba.actual_payment_amount ), 0 ) FROM csh_pay_req_ln_bank_account lnba, csh_payment_req_ln ln WHERE lnba.PAYMENT_REQ_LN_ID = ln.PAYMENT_REQ_LN_ID AND ln.payment_req_id = cprh.PAYMENT_REQ_ID ) unpaid
FROM csh_payment_req_hd cprh, con_contract cc where cprh.SOURCE_CONTRACT_ID=cc.CONTRACT_ID
and NOT EXISTS (SELECT ct.contract_id FROM csh_transaction ct WHERE ct.contract_id = cprh.SOURCE_CONTRACT_ID AND ct.transaction_type = 'PAYMENT' AND ct.source_doc_id = cprh.payment_req_id) ) v
1 = 1 and V.payment_approved_status in ('NEW','REJECTED','PART_PAID') and V.payment_req_status in ('APPROVED')
and v.payment_req_number = #{paymentReqNumber}
and v.proposed_launch_date = to_date(#{proposedLaunchDate},'yyyy-mm-dd')
and v.application_name = #{applicationName}
and v.application_date = to_date(#{applicationDate},'yyyy-mm-dd')
and v.loan_total_amount = #{loanTotalAmount}
and v.project_manager_id_n = #{projectManagerIdN}
and v.payment_approved_status = #{paymentApprovedStatus}
and v.bp_name like concat('%',concat(#{bpName},'%'))
and v.contract_number like concat('%',concat(#{contractNumber},'%'))
and v.legal_contract_number like concat('%',concat(#{legal_contract_number},'%'))
order by v.payment_req_number desc

SELECT v.* FROM (SELECT (SELECT pq.currency FROM prj_quotation pq WHERE pq.QUOTATION_ID = cc.QUOTATION_ID) AS currency, (SELECT pq.price_list FROM prj_quotation pq WHERE pq.QUOTATION_ID = cc.QUOTATION_ID) AS price_list, cc.QUOTATION_ID, cc.contract_id, cc.contract_id AS funding_plan_id, cprh.payment_req_id, cprh.LOAN_TYPE, cprh.PAYMENT_TYPE, cprh.Payment_Req_Status, cprh.PAYMENT_APPROVED_STATUS, (SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'PAYMENT_APPROVED_STATUS' AND code_value = cprh.PAYMENT_APPROVED_STATUS) AS PAYMENT_APPROVED_STATUS_N, (SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'CSH.LOAN_TYPE' AND code_value = cprh.LOAN_TYPE) AS LOAN_TYPE_N, (SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'CSH701_TRANSACTION_TYPE' AND code_value = cprh.payment_type) AS PAYMENT_TYPE_N, (SELECT e.NAME FROM sys_user s, sys_user_allocation a, fnd_employee e, fnd_employee_assigns fa WHERE s.user_id = a.user_id AND a.EMPLOYEE_ASSIGN_ID = fa.EMPLOYEE_ASSIGN_ID AND fa.EMPLOYEE_ID = e.EMPLOYEE_ID
and a.USER_ID=cprh.EMPLOYEE_ID and fa.PRIMARY_POSITION_FLAG = 'Y') AS project_manager_id_n, cprh.loan_total_amount, cprh.payment_req_number, (SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'HLS_WFL_STATUS' AND code_value = cprh.transfer_status) AS status_n, (SELECT p.CONTRACT_NUMBER FROM prj_project p WHERE p.project_id = cc.PROJECT_ID) AS contract_number, (SELECT p.tenant_id FROM prj_project p WHERE p.project_id = cc.PROJECT_ID) AS tenant_id, (SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = (SELECT p.tenant_id FROM prj_project p WHERE p.project_id = cc.PROJECT_ID)) AS bp_name, cc.contract_number AS defray_number, cprh.proposed_launch_date, cprh.created_by, cprh.creation_date, (SELECT su.description FROM sys_user su WHERE su.user_id = cprh.created_by) AS application_name, cprh.creation_date AS application_date, cprh.process_instance_id, cc.CONTRACT_NUMBER AS FUNDING_PLAN_NUMBER, (SELECT pp.COMPANY_SPV FROM prj_project pp WHERE pp.PROJECT_ID = cc.PROJECT_ID) AS COMPANY_SPV, (SELECT tc.PROJECT_ID FROM con_contract tc WHERE tc.CONTRACT_ID = cprh.SOURCE_CONTRACT_ID) PROJECT_ID, (SELECT t.company_full_name FROM fnd_company t WHERE t.company_id = (SELECT pp.COMPANY_SPV FROM prj_project pp WHERE pp.PROJECT_ID = cc.PROJECT_ID)) AS company_spv_n FROM csh_payment_req_hd cprh, con_contract cc WHERE cprh.SOURCE_CONTRACT_ID = cc.CONTRACT_ID and cprh.PAYMENT_APPROVED_STATUS IN ( 'APPROVING', 'APPROVED','PAID','PART_PAID' ) ) v
1 = 1 and V.payment_req_status in ('APPROVED')
and v.payment_req_number = #{paymentReqNumber}
and v.payment_approved_status = #{paymentApprovedStatus}
AND v.bp_name LIKE CONCAT(concat('%',#{bpName}),'%')
AND v.CONTRACT_NUMBER LIKE CONCAT(concat('%',#{contractNumber}),'%')
and v.proposed_launch_date = #{proposedLaunchDate}
and v.application_name = #{applicationName}
and v.application_date = #{applicationDate}
and v.loan_total_amount = #{loanTotalAmount}
and v.project_manager_id_n = #{projectManagerIdN}
and v.proposed_launch_date >= to_date(#{proposedLaunchDateFrom}, 'yyyy-mm-dd')
and v.proposed_launch_date <= to_date(#{proposedLaunchDateTo}, 'yyyy-mm-dd')
order by v.payment_req_number desc

SELECT SU.DESCRIPTION USER_NAME, CT.TRANSACTION_ID, CT.COMPANY_ID, CT.TRANSACTION_DATE, nvl(WRIOFF.CSH_WRITE_OFF_AMOUNT,0) WRITE_OFF_AMOUNT, WRIOFF.WRITE_OFF_TYPE, WRIOFF.CONTRACT_NUMBER, WRIOFF.CONTRACT_NAME, WRIOFF.CONTRACT_ID, WRIOFF.CON_CATEGORY SOURCE_DOC_CATEGORY, nvl(CBA.BANK_ACCOUNT_NAME,'--') BANK_ACCOUNT_NAME, nvl(CBA.BANK_ACCOUNT_NUM,'--') BANK_ACCOUNT_NUM, nvl(CBA.BANK_BRANCH_NAME,'--') BANK_BRANCH_NAME, nvl(CB.BANK_NAME,'--') BANK_NAME, nvl(CBA.CURRENCY,'CNY') CURRENCY, FC.COMPANY_FULL_NAME, nvl(CT.BP_BANK_ACCOUNT_NAME,'--') BP_BANK_ACCOUNT_NAME, nvl(CT.BP_BANK_ACCOUNT_NUM,'--') BP_BANK_ACCOUNT_NUM, nvl(CT.BP_BANK_BRANCH_NAME,'--') BP_BANK_BRANCH_NAME, nvl(CT.BP_BANK_NAME,'--') BP_BANK_NAME, nvl(HBM.BP_CODE,'--') BP_CODE, nvl(HBM.BP_NAME,'--') BP_NAME, nvl(HBM.BP_TYPE,'--') BP_TYPE, (SELECT description FROM HLS_BP_TYPE bpt where bpt.bp_type = HBM.bp_type and bpt.enabled_flag = 'Y') BP_TYPE_N, CT.TRANSACTION_TYPE, nvl( ( SELECT SUM(CWO.CSH_WRITE_OFF_AMOUNT) FROM CSH_WRITE_OFF CWO WHERE CWO.CSH_TRANSACTION_ID = CT.TRANSACTION_ID AND CWO.WRITE_OFF_TYPE = 'PAYMENT_DEBT'),0) AS PAYMENT_AMOUNT , nvl( ( SELECT SUM(CWO.CSH_WRITE_OFF_AMOUNT) FROM CSH_WRITE_OFF CWO WHERE CWO.CSH_TRANSACTION_ID = CT.TRANSACTION_ID AND CWO.WRITE_OFF_TYPE IN ('RECEIPT_CREDIT', 'RECEIPT_DEPOSIT')),0) AS DEDUCT_AMOUNT FROM CSH_TRANSACTION CT JOIN SYS_USER SU ON SU.USER_ID=CT.CREATED_BY JOIN FND_COMPANY FC ON FC.COMPANY_ID=CT.COMPANY_ID LEFT JOIN HLS_BP_MASTER HBM ON CT.BP_ID=HBM.BP_ID LEFT JOIN CSH_BANK_ACCOUNT CBA ON CBA.BANK_ACCOUNT_ID=CT.BANK_ACCOUNT_ID LEFT JOIN CSH_BANK CB ON CB.BANK_ID=CBA.BANK_ID LEFT JOIN ( SELECT CWO.CSH_TRANSACTION_ID, MAX(CON.CONTRACT_ID) CONTRACT_ID, MAX(CON.CON_CATEGORY) CON_CATEGORY, SUM(CWO.CSH_WRITE_OFF_AMOUNT) CSH_WRITE_OFF_AMOUNT, MAX(CWO.WRITE_OFF_TYPE) WRITE_OFF_TYPE, MAX(CON.CONTRACT_NUMBER) CONTRACT_NUMBER, MAX(CON.CONTRACT_NAME) CONTRACT_NAME FROM CSH_WRITE_OFF CWO LEFT JOIN ( SELECT CC.CONTRACT_ID, CC.CONTRACT_NUMBER, CC.CONTRACT_NAME, 'CON_CONTRACT' CON_CATEGORY FROM CON_CONTRACT CC WHERE CC.DATA_CLASS='NORMAL' UNION ALL SELECT CC.CONTRACT_ID, CC.CONTRACT_NUMBER, CC.CONTRACT_NAME, 'FCT_CONTRACT' CON_CATEGORY FROM FCT_CONTRACT CC WHERE CC.DATA_CLASS='NORMAL' ) CON ON CON.CONTRACT_ID=CWO.CONTRACT_ID AND CON.CON_CATEGORY=CWO.WRITE_OFF_DOC_CATEGORY GROUP BY CWO.CSH_TRANSACTION_ID) WRIOFF ON WRIOFF.CSH_TRANSACTION_ID=CT.TRANSACTION_ID WHERE CT.BUSINESS_TYPE IN('PAYMENT','DEDUCTION') AND CT.REVERSED_FLAG='N' AND CT.TRANSACTION_TYPE!='REFUND' AND CT.COMPANY_ID=#{request.companyId}
AND CT.TRANSACTION_DATE >= #{queryDateFrom}
AND CT.TRANSACTION_DATE <= #{queryDateTo}
AND WRIOFF.CONTRACT_NUMBER LIKE CONCAT(concat('%',#{contractNumber}),'%')
AND (HBM.BP_CODE LIKE CONCAT(concat('%',#{payInfo}),'%') OR HBM.BP_NAME LIKE CONCAT(concat('%',#{payInfo}),'%') )
AND (CT.BP_BANK_ACCOUNT_NAME LIKE CONCAT(concat('%',#{bankInfo}),'%') OR CT.BP_BANK_ACCOUNT_NUM LIKE CONCAT(concat('%',#{bankInfo}),'%') )
AND ( WRIOFF.CONTRACT_NUMBER LIKE CONCAT(concat('%',#{contractInfo}),'%') OR WRIOFF.CONTRACT_NAME LIKE CONCAT(concat('%',#{contractInfo}),'%') )
AND nvl(CBA.CURRENCY,'CNY') in
#{item}
ORDER BY CT.TRANSACTION_DATE desc
